// 逆变换常数矩阵
const float inv_rot[3][3] = {
    {0.55520, 0.07290, 39.68490},
    {-2.30680, 3.45080, 47.54820},
    {-0.00620, -0.00010, 1.00000}
};

// 坐标映射函数 X
float Xrot_point(uint8 x, uint8 y)
{
    // x>>2 和 y>>2 相当于 x/4 和 y/4，即在大图中寻找缩小图的对应点
    // 除以 100.0f 是为了还原之前的扩大倍数
    return (float)mapx_s[y >> 2][x >> 2] / 100.0f;
}

// 坐标映射函数 Y
float Yrot_point(uint8 x, uint8 y)
{
    return (float)mapy_s[y >> 2][x >> 2] / 100.0f;
}

// 以下公式函数直接计算，不使用大数组，节省空间
float inv_rot_x(float x, float y)
{
    return ((inv_rot[1][0] * y + inv_rot[1][1] * x + inv_rot[1][2]) / (inv_rot[2][0] * y + inv_rot[2][1] * x + 1.0f));
}

float inv_rot_y(float x, float y)
{
    return ((inv_rot[0][0] * y + inv_rot[0][1] * x + inv_rot[0][2]) / (inv_rot[2][0] * y + inv_rot[2][1] * x + 1.0f));
}

float XShowRotimg(uint8 x, uint8 y)
{
    float fx = (float)x;
    float fy = (float)y;
    return (fy * inv_rot[1][0] + fx * inv_rot[1][1] + inv_rot[1][2]) / (fy * inv_rot[2][0] + fx * inv_rot[2][1] + 1.0f);
}

float YShowRotimg(uint8 x, uint8 y)
{
    float fx = (float)x;
    float fy = (float)y;
    return (fy * inv_rot[0][0] + fx * inv_rot[0][1] + inv_rot[0][2]) / (fy * inv_rot[2][0] + fx * inv_rot[2][1] + 1.0f);
}

